@page "/apply"
@using sv_55cd2ebde8ef4c6996959365c61bac17.Models
@using sv_55cd2ebde8ef4c6996959365c61bac17.Services
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h1>Job Application</h1>

    @* Step Indicator Bar *@
    <div class="step-indicator">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var stepIndex = i;
            var stepClass = GetStepClass(stepIndex);
            <div class="step @stepClass" @onclick="() => GoToStep(stepIndex)">
                <div class="step-circle">
                    @if (IsStepCompleted(stepIndex))
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <div class="step-label">@StepNames[stepIndex]</div>
            </div>
            @if (stepIndex < StepNames.Length - 1)
            {
                <div class="step-connector @(IsStepCompleted(stepIndex) ? "completed" : "")"></div>
            }
        }
    </div>

    @* Validation Errors *@
    @if (errors.Count > 0)
    {
        <div class="validation-errors">
            <ul>
                @foreach (var error in errors)
                {
                    <li>@error</li>
                }
            </ul>
        </div>
    }

    @* Step Content *@
    @if (!isSubmitted)
    {
        @switch (currentStep)
        {
            case 0:
                @RenderPersonalInfo();
                break;
            case 1:
                @RenderWorkHistory();
                break;
            case 2:
                @RenderReferences();
                break;
            case 3:
                @RenderCoverLetter();
                break;
            case 4:
                @RenderReviewSubmit();
                break;
        }
    }
    else
    {
        <div class="submission-confirmation">
            <h2>&#10003; Application Submitted Successfully!</h2>
            <p>Your application ID is: <strong>@submittedApplicationId</strong></p>
            <p>Thank you for applying. We will review your application and get back to you.</p>
        </div>
    }
</div>

@* Step 1: Personal Info *@
@{ RenderFragment RenderPersonalInfo() =>
    @<div class="step-content">
        <h2>Personal Information</h2>
        <div class="form-group">
            <label for="fullName">Full Name *</label>
            <input id="fullName" type="text" @bind="fullName" @bind:event="oninput" placeholder="Enter your full name" />
        </div>
        <div class="form-group">
            <label for="email">Email *</label>
            <input id="email" type="email" @bind="email" @bind:event="oninput" placeholder="Enter your email" />
        </div>
        <div class="form-group">
            <label for="phone">Phone *</label>
            <input id="phone" type="tel" @bind="phone" @bind:event="oninput" placeholder="Enter your phone number" />
        </div>
        <div class="form-group">
            <label for="address">Address *</label>
            <textarea id="address" @bind="address" @bind:event="oninput" placeholder="Enter your address" rows="3"></textarea>
        </div>
        <div class="step-buttons">
            <button class="btn-primary" @onclick="NextStep" disabled="@isProcessing">
                @if (isProcessing) { <span>Validating...</span> } else { <span>Next</span> }
            </button>
        </div>
    </div>;
}

@* Step 2: Work History *@
@{ RenderFragment RenderWorkHistory() =>
    @<div class="step-content">
        <h2>Work History</h2>
        @for (int i = 0; i < workEntries.Count; i++)
        {
            var index = i;
            <div class="work-entry-card">
                <div class="work-entry-header">
                    <h3>Position @(index + 1)</h3>
                    @if (workEntries.Count > 1)
                    {
                        <button class="btn-danger-sm" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                    }
                </div>
                <div class="form-group">
                    <label>Company Name *</label>
                    <input type="text" @bind="workEntries[index].Company" @bind:event="oninput" placeholder="Company name" />
                </div>
                <div class="form-group">
                    <label>Job Title *</label>
                    <input type="text" @bind="workEntries[index].Title" @bind:event="oninput" placeholder="Job title" />
                </div>
                <div class="form-row">
                    <div class="form-group">
                        <label>Start Date *</label>
                        <input type="date" @bind="workEntries[index].StartDate" />
                    </div>
                    <div class="form-group">
                        <label>End Date</label>
                        <input type="date" @bind="workEntries[index].EndDate" disabled="@workEntries[index].IsCurrent" />
                    </div>
                </div>
                <div class="form-group checkbox-group">
                    <input type="checkbox" id="current-@index" @bind="workEntries[index].IsCurrent" />
                    <label for="current-@index">I currently work here</label>
                </div>
                <div class="form-group">
                    <label>Description *</label>
                    <textarea @bind="workEntries[index].Description" @bind:event="oninput" placeholder="Describe your responsibilities" rows="3"></textarea>
                </div>
            </div>
        }
        <button class="btn-secondary" @onclick="AddWorkEntry">+ Add Another Position</button>
        <div class="step-buttons">
            <button class="btn-outline" @onclick="PreviousStep">Back</button>
            <button class="btn-primary" @onclick="NextStep">Next</button>
        </div>
    </div>;
}

@* Step 3: References *@
@{ RenderFragment RenderReferences() =>
    @<div class="step-content">
        <h2>References</h2>
        <p class="hint">Please provide 2-3 professional references.</p>
        @for (int i = 0; i < references.Count; i++)
        {
            var index = i;
            <div class="reference-card">
                <div class="work-entry-header">
                    <h3>Reference @(index + 1)</h3>
                    @if (references.Count > 2)
                    {
                        <button class="btn-danger-sm" @onclick="() => RemoveReference(index)">Remove</button>
                    }
                </div>
                <div class="form-group">
                    <label>Name *</label>
                    <input type="text" @bind="references[index].Name" @bind:event="oninput" placeholder="Reference name" />
                </div>
                <div class="form-group">
                    <label>Relationship *</label>
                    <input type="text" @bind="references[index].Relationship" @bind:event="oninput" placeholder="e.g., Former Manager" />
                </div>
                <div class="form-row">
                    <div class="form-group">
                        <label>Email *</label>
                        <input type="email" @bind="references[index].Email" @bind:event="oninput" placeholder="Email address" />
                    </div>
                    <div class="form-group">
                        <label>Phone *</label>
                        <input type="tel" @bind="references[index].Phone" @bind:event="oninput" placeholder="Phone number" />
                    </div>
                </div>
            </div>
        }
        @if (references.Count < 3)
        {
            <button class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
        }
        <div class="step-buttons">
            <button class="btn-outline" @onclick="PreviousStep">Back</button>
            <button class="btn-primary" @onclick="NextStep">Next</button>
        </div>
    </div>;
}

@* Step 4: Cover Letter *@
@{ RenderFragment RenderCoverLetter() =>
    @<div class="step-content">
        <h2>Cover Letter</h2>
        <div class="form-group">
            <label for="coverLetter">Write your cover letter *</label>
            <textarea id="coverLetter" @bind="coverLetter" @bind:event="oninput" placeholder="Tell us why you're a great fit for this role..." rows="12" maxlength="2000"></textarea>
            <div class="char-count @(coverLetter.Length > 1800 ? "warning" : "")">
                @coverLetter.Length / 2000 characters
            </div>
        </div>
        <div class="step-buttons">
            <button class="btn-outline" @onclick="PreviousStep">Back</button>
            <button class="btn-primary" @onclick="NextStep">Next</button>
        </div>
    </div>;
}

@* Step 5: Review & Submit *@
@{ RenderFragment RenderReviewSubmit() =>
    @<div class="step-content">
        <h2>Review & Submit</h2>
        <p>Please review your application before submitting.</p>

        <div class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button class="btn-link" @onclick="() => GoToStep(0)">Edit</button>
            </div>
            <dl>
                <dt>Full Name</dt><dd>@fullName</dd>
                <dt>Email</dt><dd>@email</dd>
                <dt>Phone</dt><dd>@phone</dd>
                <dt>Address</dt><dd>@address</dd>
            </dl>
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
                <button class="btn-link" @onclick="() => GoToStep(1)">Edit</button>
            </div>
            @foreach (var entry in workEntries)
            {
                <div class="review-work-entry">
                    <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                    <span class="review-dates">@entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</span>
                    <p>@entry.Description</p>
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>References</h3>
                <button class="btn-link" @onclick="() => GoToStep(2)">Edit</button>
            </div>
            @foreach (var r in references)
            {
                <div class="review-reference">
                    <strong>@r.Name</strong> (@r.Relationship)<br />
                    @r.Email | @r.Phone
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>Cover Letter</h3>
                <button class="btn-link" @onclick="() => GoToStep(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@coverLetter</p>
        </div>

        <div class="step-buttons">
            <button class="btn-outline" @onclick="PreviousStep">Back</button>
            <button class="btn-primary btn-submit" @onclick="SubmitApplication" disabled="@isProcessing">
                @if (isProcessing) { <span>Submitting...</span> } else { <span>Submit Application</span> }
            </button>
        </div>
    </div>;
}

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int currentStep = 0;
    private bool isProcessing = false;
    private bool isSubmitted = false;
    private int? submittedApplicationId;
    private List<string> errors = new();

    // Step 1 fields
    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";

    // Step 2 fields
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };

    // Step 3 fields
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4 fields
    private string coverLetter = "";

    private string GetStepClass(int step)
    {
        if (step == currentStep) return "active";
        if (IsStepCompleted(step)) return "completed";
        return "future";
    }

    private bool IsStepCompleted(int step) => step < currentStep;

    private void GoToStep(int step)
    {
        if (step < currentStep)
        {
            errors.Clear();
            currentStep = step;
        }
    }

    private async Task NextStep()
    {
        errors.Clear();

        if (!ValidateCurrentStep())
            return;

        if (currentStep == 0)
        {
            isProcessing = true;
            try
            {
                var isValidEmail = await ApplicationService.ValidateEmailAsync(email);
                if (!isValidEmail)
                {
                    errors.Add("The email address could not be validated. Please check and try again.");
                    return;
                }
            }
            finally
            {
                isProcessing = false;
            }
        }

        currentStep++;
    }

    private void PreviousStep()
    {
        errors.Clear();
        if (currentStep > 0)
            currentStep--;
    }

    private bool ValidateCurrentStep()
    {
        switch (currentStep)
        {
            case 0:
                if (string.IsNullOrWhiteSpace(fullName)) errors.Add("Full name is required.");
                if (string.IsNullOrWhiteSpace(email)) errors.Add("Email is required.");
                if (string.IsNullOrWhiteSpace(phone)) errors.Add("Phone is required.");
                if (string.IsNullOrWhiteSpace(address)) errors.Add("Address is required.");
                break;
            case 1:
                for (int i = 0; i < workEntries.Count; i++)
                {
                    var entry = workEntries[i];
                    if (string.IsNullOrWhiteSpace(entry.Company)) errors.Add($"Position {i + 1}: Company name is required.");
                    if (string.IsNullOrWhiteSpace(entry.Title)) errors.Add($"Position {i + 1}: Job title is required.");
                    if (entry.StartDate == default) errors.Add($"Position {i + 1}: Start date is required.");
                    if (string.IsNullOrWhiteSpace(entry.Description)) errors.Add($"Position {i + 1}: Description is required.");
                }
                break;
            case 2:
                for (int i = 0; i < references.Count; i++)
                {
                    var r = references[i];
                    if (string.IsNullOrWhiteSpace(r.Name)) errors.Add($"Reference {i + 1}: Name is required.");
                    if (string.IsNullOrWhiteSpace(r.Relationship)) errors.Add($"Reference {i + 1}: Relationship is required.");
                    if (string.IsNullOrWhiteSpace(r.Email)) errors.Add($"Reference {i + 1}: Email is required.");
                    if (string.IsNullOrWhiteSpace(r.Phone)) errors.Add($"Reference {i + 1}: Phone is required.");
                }
                break;
            case 3:
                if (string.IsNullOrWhiteSpace(coverLetter)) errors.Add("Cover letter is required.");
                break;
        }

        return errors.Count == 0;
    }

    private void AddWorkEntry() => workEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index)
    {
        if (workEntries.Count > 1)
            workEntries.RemoveAt(index);
    }

    private void AddReference()
    {
        if (references.Count < 3)
            references.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (references.Count > 2)
            references.RemoveAt(index);
    }

    private async Task SubmitApplication()
    {
        isProcessing = true;
        errors.Clear();

        try
        {
            var personal = new PersonalInfo(fullName, email, phone, address);
            var work = new WorkHistory(workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)
            ).ToList());
            var refs = references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
            var application = new JobApplication(personal, work, refs, coverLetter);

            submittedApplicationId = await ApplicationService.SubmitApplicationAsync(application);
            isSubmitted = true;
        }
        catch (Exception ex)
        {
            errors.Add($"Submission failed: {ex.Message}");
        }
        finally
        {
            isProcessing = false;
        }
    }

    private class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
