.apply-container {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

.apply-container h1 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    min-width: 80px;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.85rem;
    border: 2px solid #ddd;
    background: #fff;
    color: #999;
    transition: all 0.2s;
}

.step.active .step-circle {
    border-color: #4361ee;
    background: #4361ee;
    color: #fff;
}

.step.completed .step-circle {
    border-color: #2ec4b6;
    background: #2ec4b6;
    color: #fff;
}

.step.future .step-circle {
    border-color: #ddd;
    background: #f8f8f8;
    color: #bbb;
}

.step-label {
    margin-top: 0.4rem;
    font-size: 0.7rem;
    text-align: center;
    color: #999;
    white-space: nowrap;
}

.step.active .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step.completed .step-label {
    color: #2ec4b6;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #ddd;
    min-width: 20px;
    max-width: 60px;
    margin: 0 0.25rem;
    align-self: center;
    margin-bottom: 1.2rem;
}

.step-connector.completed {
    background: #2ec4b6;
}

/* Validation Errors */
.validation-errors {
    background: #fff0f0;
    border: 1px solid #ffcdd2;
    border-radius: 8px;
    padding: 1rem;
    margin-bottom: 1.5rem;
}

.validation-errors ul {
    margin: 0;
    padding-left: 1.2rem;
}

.validation-errors li {
    color: #c62828;
    font-size: 0.9rem;
    margin-bottom: 0.25rem;
}

/* Step Content */
.step-content {
    background: #fff;
    border: 1px solid #e8e8e8;
    border-radius: 12px;
    padding: 2rem;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
}

.step-content h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #1a1a2e;
}

/* Form Elements */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    font-size: 0.9rem;
    color: #333;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
